// Some portions generated by Claude
/**
 * A deterministic, synthetic knowledge graph shaped like the query results the Graph page loads: typed resources in
 * communities, organisations as hubs with skewed membership, concept and place hierarchies, citation and event chains,
 * blank address nodes, long-range links, isolated resources, and literal values and rdf:type statements the canvas
 * does not draw. `resources` is exactly the number of nodes the canvas draws and lays out.
 *
 * The result is SPARQL Results JSON (?source ?predicate ?target), as the Graph servlet answers it: blank nodes carry
 * the repository's reference flag.
 */
const EX = "https://example.org/data/";
const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const RDFS_LABEL = "http://www.w3.org/2000/01/rdf-schema#label";
const XSD = "http://www.w3.org/2001/XMLSchema#";
const P = (name) => `${EX}vocab/${name}`;

/** Shares of the drawn resources, by kind; addresses are blank nodes. */
const SHARES = [
  ["person", 0.4],
  ["document", 0.22],
  ["concept", 0.15],
  ["event", 0.1],
  ["place", 0.08],
  ["organization", 0.03],
  ["address", 0.02],
];

function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

export function representativeResults(resources, seed = 20261017) {
  const next = random(seed);
  const pick = (list) => list[Math.floor(next() * list.length)];
  const between = (low, high) => low + Math.floor(next() * (high - low + 1));
  const ids = {};
  let assigned = 0;
  SHARES.forEach(([kind, share], index) => {
    const count = index === SHARES.length - 1 ? resources - assigned : Math.max(1, Math.round(resources * share));
    ids[kind] = Array.from({ length: count }, (_, i) => (kind === "address" ? `address-${i}` : `${EX}${kind}/${i}`));
    assigned += count;
  });
  const bindings = [];
  const term = (value) => (value.startsWith("address-")
    ? { type: "bnode", value, "rdf4j:reference": true }
    : { type: "uri", value });
  const link = (source, predicate, target) =>
    bindings.push({ source: term(source), predicate: { type: "uri", value: predicate }, target: term(target) });
  const value = (source, predicate, literal) =>
    bindings.push({ source: term(source), predicate: { type: "uri", value: predicate }, target: literal });

  // Types (drawn as colours, not links) and values (drawn only when values are shown).
  for (const [kind, list] of Object.entries(ids)) {
    const classes = Array.from({ length: kind === "person" || kind === "document" ? 4 : 2 }, (_, i) => `${EX}class/${kind}-${i}`);
    list.forEach((id, i) => {
      link(id, RDF_TYPE, classes[i % classes.length]);
      if (kind !== "address") {
        value(id, RDFS_LABEL, i % 3
          ? { type: "literal", value: `${kind[0].toUpperCase()}${kind.slice(1)} ${i} — ${pick(["north", "harbour", "archive", "studio", "field"])}` }
          : { type: "literal", value: `${kind} ${i}`, "xml:lang": pick(["en", "nb", "de"]) });
      }
    });
  }
  // Organisations are hubs: membership follows a skewed (Zipf-like) distribution.
  const organizationWeights = ids.organization.map((_, rank) => 1 / (rank + 1));
  const total = organizationWeights.reduce((sum, weight) => sum + weight, 0);
  const organization = () => {
    let target = next() * total;
    for (let i = 0; i < organizationWeights.length; i++) {
      target -= organizationWeights[i];
      if (target <= 0) return i;
    }
    return organizationWeights.length - 1;
  };
  const community = [];
  ids.person.forEach((person, i) => {
    const home = organization();
    community[i] = home;
    link(person, P("memberOf"), ids.organization[home]);
    value(person, P("age"), { type: "literal", value: String(between(18, 90)), datatype: `${XSD}integer` });
  });
  // Colleagues know each other: links stay mostly within a community of nearby people.
  ids.person.forEach((person, i) => {
    for (let k = between(1, 3); k > 0; k--) {
      const other = Math.min(ids.person.length - 1, Math.max(0, i + between(-60, 60)));
      if (other !== i) link(person, P("knows"), ids.person[other]);
    }
  });
  // Concept and place hierarchies.
  ids.concept.forEach((concept, i) => {
    if (i) link(concept, P("broader"), ids.concept[Math.floor((i - 1) / between(2, 8))]);
    if (i > 10 && next() < 0.2) link(concept, P("related"), pick(ids.concept));
  });
  ids.place.forEach((place, i) => {
    if (i) link(place, P("locatedIn"), ids.place[Math.floor((i - 1) / 6)]);
  });
  // Documents: authors (mostly colleagues), subjects, and citations of earlier documents; a few have no links at all.
  ids.document.forEach((document, i) => {
    value(document, P("date"), { type: "literal", value: `20${String(10 + (i % 16)).padStart(2, "0")}-0${1 + (i % 9)}-1${i % 9}`, datatype: `${XSD}date` });
    if (i % 97 === 0) return;
    const lead = between(0, ids.person.length - 1);
    for (let k = between(1, 4); k > 0; k--) {
      link(document, P("author"), ids.person[Math.min(ids.person.length - 1, lead + between(0, 30))]);
    }
    for (let k = between(1, 2); k > 0; k--) link(document, P("about"), pick(ids.concept));
    if (i > 5) for (let k = between(0, 2); k > 0; k--) link(document, P("cites"), ids.document[between(Math.max(0, i - 400), i - 1)]);
  });
  // Events form chains (series), happen at places and have participants.
  ids.event.forEach((event, i) => {
    if (i % 20) link(event, P("follows"), ids.event[i - 1]);
    link(event, P("location"), pick(ids.place));
    const around = between(0, ids.person.length - 1);
    for (let k = between(2, 5); k > 0; k--) link(event, P("participant"), ids.person[Math.min(ids.person.length - 1, around + k * 7)]);
  });
  // Blank addresses: person -> address -> place.
  ids.address.forEach((address, i) => {
    link(ids.person[(i * 13) % ids.person.length], P("address"), address);
    link(address, P("locality"), pick(ids.place));
  });
  // A few long-range links across communities.
  const all = Object.values(ids).flat().filter((id) => !id.startsWith("address-"));
  for (let k = Math.round(resources * 0.03); k > 0; k--) link(pick(all), P("seeAlso"), pick(all));

  return { head: { vars: ["source", "predicate", "target"] }, results: { bindings } };
}
